import type { Metadata } from "next";
import Link from "next/link";
import { redirect } from "next/navigation";
import { createServerSupabase } from "@/lib/supabase/server";
import VendorSettings from "@/components/VendorSettings";
export const metadata:Metadata={title:"Settings"};
export default async function SettingsPage(){const supabase=await createServerSupabase();const {data:{user}}=await supabase.auth.getUser();if(!user)redirect("/login?next=%2Fdashboard%2Fvendor%2Fsettings");const [{data:profile},{data:vendor}]=await Promise.all([supabase.from("profiles").select("role,full_name,contact_email,phone").eq("id",user.id).maybeSingle(),supabase.from("vendors").select("momo_number,momo_network,slug").eq("owner_id",user.id).maybeSingle()]);if(profile?.role!=="vendor")redirect("/dashboard/agent");if(!vendor)return <main className="container py-12">Shop details could not be found.</main>;return <main className="container py-8 sm:py-12 sp-page sp-page--vendor-settings"><header className="mb-6"><Link href="/dashboard/vendor" className="muted text-sm underline">← Your shop</Link><h1 className="display mt-3 text-4xl font-bold">Settings</h1><p className="muted mt-2">Update your contact information and the MoMo account that receives payouts.</p><p className="mt-3 text-sm">Shop link: <b>{vendor.slug}.seepay.shop</b> <span className="muted">· Contact support to change it.</span></p></header><VendorSettings initialName={profile.full_name} initialEmail={profile.contact_email||""} phone={vendor.momo_number} network={vendor.momo_network as "MTN"|"VODAFONE"|"AIRTELTIGO"}/></main>}
